-- CONTAS DA CASA — v10
-- Execute este arquivo UMA VEZ no Supabase > SQL Editor antes de publicar a v10.

-- 1. Pagamento dividido em um único lançamento
alter table public.lancamentos
  add column if not exists payment_split jsonb;

-- 2. Histórico mensal consolidado e privado
create table if not exists public.historico_mensal (
  competence text primary key,
  payload jsonb not null,
  updated_at timestamptz not null default now()
);

alter table public.historico_mensal enable row level security;

drop policy if exists "usuarios autenticados podem ler historico"
on public.historico_mensal;

create policy "usuarios autenticados podem ler historico"
on public.historico_mensal
for select
to authenticated
using (true);

revoke all on table public.historico_mensal from anon;
grant select on table public.historico_mensal to authenticated;

-- 3. Importação do histórico JAN–JUL/2026.
-- Os dados ficam no banco privado; não entram no GitHub.

